  const p0 = { ...(inputs.b || {}) }; const JEVP = {}; for (const k of Object.keys(inputs)) if (k.indexOf('jev_') === 0 && k.slice(-11) !== '_confidence') { const f = k.slice(4), v = inputs[k], conf = Number(inputs[k + '_confidence']); const pol = JEVP[f] || [0.5, null]; if (v !== undefined && v !== '' && (isNaN(conf) || conf >= pol[0])) p0[f] = v; else if (pol[1] !== null && pol[1] !== undefined) p0[f] = pol[1]; } /* a Jev answer lands only when confident; else the fallback */ const now = new Date().toISOString();
  const p = { ...p0 }; for (const [k, c] of Object.entries({})) if (p0[k] !== undefined) p[c] = p0[k];
  const allowed = ["Student_ID", "Enrolled_At", "Name", "Student_Phone", "Parent_Name", "Parent_Phone", "Course", "Batch", "Address", "Status", "Attendance_Pct", "Last_Score", "Avg_Score", "Class_Rank", "Strong_Subjects", "Weak_Subjects", "Performance_Trend", "Fee_Status", "Fee_Amount_INR", "Fee_Due_Date", "Mentor", "Counsellor", "Issue_Type", "Main_Issue", "Last_Counselled_At", "Last_Report_At", "Last_Parent_Call_At", "Parent_Sentiment", "Parent_Concern"];
  const patch = {}; for (const k of allowed) if (p[k] !== undefined && p[k] !== null && p[k] !== '') patch[k] = p[k];
  patch["Last_Report_At"] = now;
  if (p.Stage && ['Won','Lost','Closed'].includes(p.Stage) && !p.Close_Reason) return { ok: 'false', error: 'Close_Reason required' };
  return { ok: 'true', patch, id: p[allowed[0]] || '' };
};

